<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>WastedToken Mint — Collectible Physical Challenge Coins</title>
<style>
:root{--bg:#07080b;--ink:#e9e7e2;--muted:#99a0ab;--gold:#d9b26a;--gold2:#f3dfae;--line:rgba(217,178,106,.2);--l2:rgba(255,255,255,.07);--serif:Georgia,"Times New Roman",serif;--sans:"Helvetica Neue",Helvetica,Arial,"Segoe UI",system-ui,sans-serif}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased;overflow-x:hidden}
body::before{content:"";position:fixed;inset:0;pointer-events:none;z-index:0;background:radial-gradient(1200px 700px at 78% -10%,rgba(217,178,106,.10),transparent 62%),radial-gradient(900px 600px at 6% 24%,rgba(90,120,200,.07),transparent 60%),radial-gradient(1000px 900px at 50% 118%,rgba(217,178,106,.05),transparent 65%)}
.wrap{position:relative;z-index:2;max-width:1240px;margin:0 auto;padding:0 26px}
header{position:sticky;top:0;z-index:50;backdrop-filter:blur(14px);background:linear-gradient(180deg,rgba(7,8,11,.94),rgba(7,8,11,.6));border-bottom:1px solid var(--l2)}
.nav{display:flex;align-items:center;gap:26px;height:72px}
.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:inherit}
.sig{width:34px;height:34px;border-radius:50%;background:radial-gradient(circle at 34% 28%,#fff6df,#e2c485 22%,#a97f36 55%,#5d4218 78%,#2a1d0a);box-shadow:0 0 0 1px rgba(217,178,106,.5),0 0 18px rgba(217,178,106,.25),inset 0 0 8px rgba(0,0,0,.5);display:grid;place-items:center;font-family:var(--serif);font-size:14px;color:#2a1d0a;font-weight:700}
.bn{font-family:var(--serif);font-size:17px;letter-spacing:.13em;text-transform:uppercase}
.bn b{font-weight:400;background:linear-gradient(180deg,var(--gold2),var(--gold));-webkit-background-clip:text;background-clip:text;color:transparent}
.bn small{display:block;font-family:var(--sans);font-size:8.5px;letter-spacing:.32em;color:var(--muted);margin-top:2px}
nav{margin-left:auto;display:flex;gap:24px}
nav a{color:var(--muted);text-decoration:none;font-size:11px;letter-spacing:.22em;text-transform:uppercase}
nav a:hover{color:var(--gold2)}
.cart{padding:9px 15px;border-radius:99px;border:1px solid var(--line);color:var(--gold2);font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;background:rgba(217,178,106,.05)}
@media(max-width:860px){nav{display:none}}
.hero{display:grid;grid-template-columns:1.02fr .98fr;gap:40px;align-items:center;padding:66px 0 40px}
.eb{display:inline-flex;align-items:center;gap:9px;font-size:10px;letter-spacing:.32em;text-transform:uppercase;color:var(--gold);border:1px solid var(--line);border-radius:99px;padding:7px 15px;margin-bottom:24px;background:rgba(217,178,106,.05)}
