h1{font-family:var(--serif);font-weight:400;font-size:clamp(40px,6.1vw,76px);line-height:.99;letter-spacing:-.02em;margin:0 0 20px}
.shine{background:linear-gradient(96deg,#7a6136,#f6e6bd 22%,#c79a4d 44%,#fff8e6 60%,#a8823f 82%,#e3c583);-webkit-background-clip:text;background-clip:text;color:transparent}
h1 em{font-style:italic;color:#cfd4de}
.lede{color:var(--muted);font-size:16px;line-height:1.72;max-width:52ch;margin:0 0 28px}
