.cta{display:flex;gap:13px;flex-wrap:wrap;margin-bottom:32px}
.btn{border:0;cursor:pointer;padding:15px 27px;border-radius:2px;font-size:11px;letter-spacing:.22em;text-transform:uppercase;text-decoration:none;font-family:var(--sans);transition:transform .2s,filter .25s}
.gold{background:linear-gradient(180deg,#f4e1b6,#d5ae66 48%,#a97f36);color:#241906;font-weight:700;box-shadow:0 10px 30px rgba(217,178,106,.2),inset 0 1px 0 rgba(255,255,255,.5)}
.ghost{border:1px solid var(--line);color:var(--ink);background:transparent}
.btn:hover{transform:translateY(-2px);filter:brightness(1.07)}
.hs{display:flex;gap:32px;flex-wrap:wrap;border-top:1px solid var(--l2);padding-top:20px}
.hs span{display:block;font-family:var(--serif);font-size:25px;color:var(--gold2)}
.hs small{display:block;font-size:9px;letter-spacing:.26em;text-transform:uppercase;color:var(--muted);margin-top:5px}
.stage{position:relative;display:grid;place-items:center;margin:0}
.stage::before{content:"";position:absolute;width:76%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle,rgba(217,178,106,.17),transparent 66%);filter:blur(38px)}
