@media(max-width:960px){.hero{grid-template-columns:1fr}.stage{order:-1}}
.tick{border-top:1px solid var(--l2);border-bottom:1px solid var(--l2);overflow:hidden;background:rgba(255,255,255,.015);position:relative;z-index:2}
.tin{display:flex;gap:50px;white-space:nowrap;padding:13px 0;animation:sl 44s linear infinite;width:max-content}
.tin span{font-size:10px;letter-spacing:.3em;text-transform:uppercase;color:var(--muted)}
.tin b{color:var(--gold);font-weight:400}
@keyframes sl{to{transform:translateX(-50%)}}
section{padding:96px 0;position:relative;z-index:2}
