(function(){
"use strict";

/* ---------- relief maps: procedural die faces -> height -> gradients ---------- */
function blur(src,n,r){
  var tmp=new Float32Array(n*n),out=new Float32Array(n*n),w=2*r+1,x,y,s;
  function cl(v){return v<0?0:(v>n-1?n-1:v);}
  for(y=0;y<n;y++){s=0;for(x=-r;x<=r;x++)s+=src[y*n+cl(x)];
    for(x=0;x<n;x++){tmp[y*n+x]=s/w;s-=src[y*n+cl(x-r)];s+=src[y*n+cl(x+r+1)];}}
  for(x=0;x<n;x++){s=0;for(y=-r;y<=r;y++)s+=tmp[cl(y)*n+x];
    for(y=0;y<n;y++){out[y*n+x]=s/w;s-=tmp[cl(y-r)*n+x];s+=tmp[cl(y+r+1)*n+x];}}
  return out;
}
function makeMap(size,draw){
  var cv=document.createElement('canvas');cv.width=cv.height=size;
  var c=cv.getContext('2d');c.fillStyle='#000';c.fillRect(0,0,size,size);
  draw(c,size);
  var px=c.getImageData(0,0,size,size).data,H=new Float32Array(size*size),i;
  for(i=0;i<size*size;i++)H[i]=px[i*4]/255;
  H=blur(H,size,2);H=blur(H,size,2);H=blur(H,size,1);
  var h2=size/2,x,y,dx,dy,r;
  for(y=0;y<size;y++)for(x=0;x<size;x++){
    dx=(x+.5-h2)/h2;dy=(y+.5-h2)/h2;r=Math.sqrt(dx*dx+dy*dy);
